struct string_rep
{
  char *data;
  int capacity;
  int length;
};

struct stringx
{
  int unused;
  string_rep *rep;
};

struct value_type
{
  stringx first;
  unsigned short second;
};

struct node
{
  int color;
  node *parent;
  node *left;
  node *right;
  value_type value;
};

struct iterator
{
  node *position;
};

struct result
{
  iterator first;
  bool second;
};

struct tree
{
  node *header;
  unsigned count;
  char compare;
};

static int string_compare(const stringx &a, const stringx &b)
{
  int n = a.rep->length < b.rep->length ? a.rep->length : b.rep->length;
  for (int i = 0; i < n; ++i)
  {
    if (a.rep->data[i] < b.rep->data[i])
      return -1;
    if (b.rep->data[i] < a.rep->data[i])
      return 1;
  }
  if (a.rep->length < b.rep->length)
    return -1;
  if (b.rep->length < a.rep->length)
    return 1;
  return 0;
}

