result insert_unique(tree *self, const value_type &value)
{
  node *y = self->header;
  node *x = y->parent;
  bool comp = true;
  while (x != 0)
  {
    y = x;
    comp = string_compare(value.first, x->value.first) < 0;
    x = comp ? x->left : x->right;
  }
  iterator j;
  j.position = y;
  if (comp)
  {
    if (j.position == self->header->left)
      return result{tree_insert(self, x, y, value), true};
    if (j.position->left != 0)
    {
      j.position = j.position->left;
      while (j.position->right != 0)
        j.position = j.position->right;
    }
    else
    {
      node *p = j.position->parent;
      while (j.position == p->left)
      {
        j.position = p;
        p = p->parent;
      }
      j.position = p;
    }
  }
  if (string_compare(j.position->value.first, value.first) < 0)
    return result{tree_insert(self, x, y, value), true};
  return result{j, false};
}
